import sys

data = sys.stdin.read().split()
n = int(data[0]); g = int(data[1])
a = [int(x) for x in data[2:2 + n]]
best = None
for mask in range(1 << (n - 1)):
    lens = []
    start = 0
    for i in range(n - 1):
        if mask >> i & 1:
            lens.append(i + 1 - start)
            start = i + 1
    lens.append(n - start)
    ok = True
    pos = 0
    for L in lens:
        if sum(a[pos:pos + L]) < g * L:
            ok = False
            break
        pos += L
    if ok:
        key = (-len(lens), lens)
        if best is None or key < best:
            best = key
if best is None:
    print(-1)
else:
    print(-best[0])
    print(' '.join(map(str, best[1])))

